import { request } from "@/lib/api"

export interface GitHubRepo {
  id: string | null
  github_id: number
  name: string
  full_name: string
  description: string | null
  html_url: string
  stargazers_count: number
  language: string | null
  private: boolean
  archived: boolean
  updated_at: string
  default_branch: string
  permission: "admin" | "maintain" | "write" | "triage" | "read"
  checkpoint_count: number | null
  runners_enabled: boolean
  auto_run_on_push: boolean
  trails_enabled: boolean
  public_sharing_enabled: boolean
}

export interface GitHubReposResponse {
  repos: GitHubRepo[]
  updated_at: string
  from_cache?: boolean
  from_db?: boolean
  syncing?: boolean // True when background job is syncing repos for new users
  sync_error?: {
    code: "initial_sync_failed"
    attempts: number
    max_attempts: number
  }
}

export async function fetchGitHubRepos(): Promise<GitHubReposResponse> {
  return request<GitHubReposResponse>("/api/v1/cache/repos")
}

export interface SyncReposResponse {
  repos: GitHubRepo[]
  prs: GitHubPR[]
  updated_at: string
  synced: boolean
  total_synced: number
}

export async function syncGitHubRepos(): Promise<SyncReposResponse> {
  return request<SyncReposResponse>("/api/v1/cache/repos/sync", {
    method: "POST",
  })
}

export interface GitHubPR {
  id: number
  number: number
  title: string
  html_url: string
  state: string
  repo_full_name: string
  created_at: string
  updated_at: string
  draft: boolean
}

export interface GitHubPRsResponse {
  prs: GitHubPR[]
  updated_at: string
  from_cache: boolean
}

export async function fetchGitHubPRs(): Promise<GitHubPRsResponse> {
  return request<GitHubPRsResponse>("/api/v1/cache/prs")
}

export interface RepoCommitActivity {
  repo_full_name: string
  weeks: number[]
}

export interface CommitActivityResponse {
  activity: RepoCommitActivity[]
  updated_at: string
  from_cache: boolean
}

export async function fetchCommitActivity(repoIds?: string[]): Promise<CommitActivityResponse> {
  const params = repoIds?.length ? `?repo_ids=${repoIds.join(",")}` : ""
  return request<CommitActivityResponse>(`/api/v1/cache/activity${params}`)
}

export interface SyncStatusResponse {
  lastUpdate: number | null
  syncInProgress: boolean
}

export async function fetchSyncStatus(): Promise<SyncStatusResponse> {
  return request<SyncStatusResponse>("/api/v1/cache/sync-status")
}

