import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query"
import { useEffect, useRef } from "react"

import { useAuth } from "@/domains/platform/auth"
import { queryClient } from "@/lib/queryClient"

import {
  fetchGitHubRepos,
  fetchGitHubPRs,
  fetchCommitActivity,
  fetchSyncStatus,
  syncGitHubRepos,
  type GitHubRepo,
  type GitHubReposResponse,
  type GitHubPR,
  type GitHubPRsResponse,
  type RepoCommitActivity,
  type CommitActivityResponse,
  type SyncStatusResponse,
} from "../api"

export type { GitHubRepo, GitHubPR, RepoCommitActivity }

// Poll sync status every 60 seconds to detect webhook-triggered and background sync updates
export function useSyncStatusQuery(enabled: boolean = true) {
  const queryClient = useQueryClient()
  const lastUpdateRef = useRef<number | null>(null)
  const hasInitializedRef = useRef<boolean>(false)
  const wasInProgressRef = useRef<boolean>(false)

  const query = useQuery<SyncStatusResponse>({
    queryKey: ["sync", "status"],
    queryFn: fetchSyncStatus,
    enabled,
    // Poll more frequently when sync is in progress
    refetchInterval: (query) => {
      const data = query.state.data
      return data?.syncInProgress ? 5_000 : 60_000 // 5s when syncing, 60s otherwise
    },
    refetchIntervalInBackground: false, // Only when tab is active
  })

  // Invalidate repo queries when lastUpdate changes or sync completes
  useEffect(() => {
    if (!enabled) return

    const newLastUpdate = query.data?.lastUpdate ?? null
    const syncInProgress = query.data?.syncInProgress ?? false

    // Skip invalidation on first load (just learning initial state, not detecting a change)
    // Wait until query.data is defined before initializing (not during loading state)
    if (!hasInitializedRef.current) {
      if (query.data === undefined) {
        return // Still loading, don't initialize yet
      }
      lastUpdateRef.current = newLastUpdate
      wasInProgressRef.current = syncInProgress
      hasInitializedRef.current = true
      return
    }

    // Detect when lastUpdate timestamp changes (including null → value for new users)
    const lastUpdateChanged = newLastUpdate !== null && newLastUpdate !== lastUpdateRef.current

    // Detect when sync completes (was in progress, now not)
    const syncCompleted = wasInProgressRef.current && !syncInProgress

    if (lastUpdateChanged || syncCompleted) {
      // Invalidate all GitHub-related queries and dashboard checkpoints
      queryClient.invalidateQueries({ queryKey: ["github"] })
      queryClient.invalidateQueries({ queryKey: ["userCheckpoints"] })
    }

    lastUpdateRef.current = newLastUpdate
    wasInProgressRef.current = syncInProgress
  }, [enabled, query.data?.lastUpdate, query.data?.syncInProgress, query.data, queryClient])

  return query
}

export function useRepositoriesQuery() {
  // /api/v1/cache/repos is behind requireAuth — skip the request entirely for
  // unauthenticated visitors (e.g. public repo pages in incognito) so it doesn't
  // 401 on every page load.
  const { isAuthenticated } = useAuth()
  const wasAuthenticated = useRef(isAuthenticated)

  // Clear cached repo data when auth is lost (logout / session expiry) so
  // stale metadata from the previous user doesn't leak to public pages.
  useEffect(() => {
    if (wasAuthenticated.current && !isAuthenticated) {
      queryClient.removeQueries({ queryKey: ["github", "repos"] })
    }
    wasAuthenticated.current = isAuthenticated
  }, [isAuthenticated])

  return useQuery<GitHubReposResponse>({
    queryKey: ["github", "repos"],
    queryFn: fetchGitHubRepos,
    enabled: isAuthenticated,
    staleTime: 30_000, // 30 seconds (reduced from 5 minutes for faster webhook response)
    // Poll when syncing is in progress (new user background job)
    refetchInterval: (query) => {
      const data = query.state.data
      return data?.syncing ? 2_000 : false
    },
  })
}

export function usePRsQuery() {
  return useQuery<GitHubPRsResponse>({
    queryKey: ["github", "prs"],
    queryFn: fetchGitHubPRs,
    staleTime: 2 * 60 * 1000, // 2 minutes - PRs change more frequently
  })
}

export function useCommitActivityQuery(repoIds?: string[]) {
  return useQuery<CommitActivityResponse>({
    queryKey: ["github", "activity", repoIds],
    queryFn: () => fetchCommitActivity(repoIds),
    staleTime: 30 * 60 * 1000, // 30 minutes - activity changes less frequently
    enabled: !repoIds || repoIds.length > 0,
  })
}

export function useSyncReposMutation() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: syncGitHubRepos,
    onSuccess: (data) => {
      // Update queries with the synced data
      queryClient.setQueryData<GitHubReposResponse>(["github", "repos"], {
        repos: data.repos,
        updated_at: data.updated_at,
        from_db: true,
      })
      queryClient.setQueryData<GitHubPRsResponse>(["github", "prs"], {
        prs: data.prs,
        updated_at: data.updated_at,
        from_cache: false,
      })
      // Invalidate activity query to refetch checkpoint activity
      queryClient.invalidateQueries({ queryKey: ["github", "activity"] })
    },
  })
}

