import { useSearch, useNavigate } from "@tanstack/react-router"
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
  type SortingState,
} from "@tanstack/react-table"
import { usePostHog } from "posthog-js/react"
import { useEffect, useMemo, useState, useCallback, useRef } from "react"

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  TableEmpty,
  TableSkeleton,
  Badge,
  Input,
  Dropdown,
  DropdownTrigger,
  DropdownContent,
  DropdownItem,
  DropdownSub,
  DropdownSubTrigger,
  DropdownSubContent,
  DropdownSubItem,
  DropdownSeparator,
  FilterPill,
  TabNav,
  TabNavItem,
  Dialog,
  DialogContent,
  DialogTitle,
  DialogBody,
  DialogFooter,
  DialogClose,
  Empty,
  EmptyMedia,
  EmptyTitle,
  EmptyDescription,
  EmptyContent,
} from "@/components"
import Button from "@/components/Button"
import { SearchIcon, FilterIcon, MoreVerticalIcon, StarIcon } from "@/components/icons"
import { Page } from "@/domains/platform/components/Page"
import { useRecentRepoActions } from "@/domains/platform/repo-preferences/hooks/useRecentRepoActions"
import { formatRelativeTime } from "@/lib/date"
import {
  parseFilterValue,
  serializeFilterValue,
  parseBooleanFilter,
  serializeBooleanFilter,
} from "@/lib/url-filters"
import type { RepositoriesSearchParams } from "@/routes/_authenticated/repositories"

import {
  useRepositoriesQuery,
  usePRsQuery,
  useCommitActivityQuery,
  useSyncReposMutation,
  useSyncStatusQuery,
  type GitHubRepo,
} from "../hooks/useRepositoriesQuery"

// Extended repo type with PR count and activity
interface RepoWithData extends GitHubRepo {
  pr_count: number
  activity: number[]
}

function slugify(text: string): string {
  const slug = text
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "") // Trim leading/trailing hyphens
  return slug || "tab" // Fallback to "tab" if empty
}

// Reserved tab IDs that cannot be used for saved tabs
const RESERVED_TAB_IDS = ["all"]

function generateUniqueSlug(text: string, existingIds: string[], currentId?: string): string {
  const baseSlug = slugify(text)
  const allReservedIds = [...existingIds, ...RESERVED_TAB_IDS]

  // If the base slug is available (or matches current ID being renamed), use it
  if (
    (!allReservedIds.includes(baseSlug) || baseSlug === currentId) &&
    !RESERVED_TAB_IDS.includes(baseSlug)
  ) {
    return baseSlug
  }

  // Otherwise, find a unique suffix
  let counter = 2
  while (
    allReservedIds.includes(`${baseSlug}-${counter}`) &&
    `${baseSlug}-${counter}` !== currentId
  ) {
    counter++
  }
  return `${baseSlug}-${counter}`
}

function formatDate(dateString: string): string {
  const date = new Date(dateString)
  return date.toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  })
}

function SortIcon({ direction }: { direction: "asc" | "desc" }) {
  return (
    <svg
      className="h-4 w-4"
      fill="none"
      viewBox="0 0 24 24"
      stroke="currentColor"
      aria-hidden="true"
    >
      {direction === "asc" ? (
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" />
      ) : (
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
      )}
    </svg>
  )
}

interface Filters {
  language: string | null
  languageOperator: "is" | "is not"
  visibility: "all" | "public" | "private"
  visibilityOperator: "is" | "is not"
  owner: string | null
  ownerOperator: "is" | "is not"
  hasOpenPRs: boolean | null
  hasCheckpoints: boolean | null
  permission: "all" | "admin" | "maintain" | "write" | "triage" | "read"
  permissionOperator: "is" | "is not"
}

type FilterKey =
  | "language"
  | "visibility"
  | "owner"
  | "hasOpenPRs"
  | "hasCheckpoints"
  | "permission"

interface SavedFilterTab {
  id: string
  name: string
  filters: Filters
  filterOrder: FilterKey[]
}

// Language colors (common languages)
const languageColors: Record<string, string> = {
  TypeScript: "bg-blue-500",
  JavaScript: "bg-yellow-400",
  Python: "bg-green-500",
  Go: "bg-cyan-500",
  Rust: "bg-orange-600",
  Ruby: "bg-red-500",
  Java: "bg-amber-600",
  "C++": "bg-pink-500",
  C: "bg-gray-500",
  "C#": "bg-purple-500",
  PHP: "bg-indigo-400",
  Swift: "bg-orange-500",
  Kotlin: "bg-violet-500",
  Scala: "bg-red-600",
  Shell: "bg-green-600",
  HTML: "bg-orange-400",
  CSS: "bg-purple-400",
  Vue: "bg-emerald-500",
  Svelte: "bg-orange-500",
}

function getLanguageColor(language: string | null): string {
  if (!language) return "bg-neutral-400"
  return languageColors[language] || "bg-neutral-400"
}

function ActivitySparkline({ data }: { data: number[] }) {
  const height = 24
  const width = 106

  // Handle empty data
  if (!data || data.length === 0) {
    return (
      <span className="text-xs text-disabled" role="img" aria-label="No activity">
        —
      </span>
    )
  }

  // Normalize data to fit in the sparkline height
  const maxValue = Math.max(...data, 1)
  const normalizedData = data.map((v) => (v / maxValue) * (height - 2))
  const totalActivity = data.reduce((sum, v) => sum + v, 0)

  return (
    <svg
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      fill="none"
      className="text-orange-500"
      role="img"
      aria-label={`Activity chart: ${totalActivity} total checkpoints over ${data.length} weeks`}
    >
      {normalizedData.map((value, i) => {
        const x = 1 + i * 2
        const barHeight = Math.max(1, value) // Minimum 1px for visibility
        return <path key={i} d={`M${x} ${height}V${height - barHeight}`} stroke="currentColor" />
      })}
    </svg>
  )
}

const columnHelper = createColumnHelper<RepoWithData>()

const columns = [
  columnHelper.accessor("full_name", {
    header: "Name",
    cell: (info) => {
      const repo = info.row.original
      return (
        <div className="flex flex-col gap-1">
          <div className="flex items-center gap-2">
            <span className="text-base font-semibold">{info.getValue()}</span>
            {repo.private && <Badge className="text-xs">Private</Badge>}
          </div>
          <div className="flex items-center gap-2 font-mono text-xs text-muted">
            {repo.language && (
              <>
                <span className={`h-2.5 w-2.5 rounded-full ${getLanguageColor(repo.language)}`} />
                <span>{repo.language}</span>
                <span>·</span>
              </>
            )}
            <span className="flex items-center gap-1">
              <StarIcon size={14} />
              {repo.stargazers_count}
            </span>
          </div>
        </div>
      )

