    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "") // Trim leading/trailing hyphens
  return slug || "tab" // Fallback to "tab" if empty
}

// Reserved tab IDs that cannot be used for saved tabs
const RESERVED_TAB_IDS = ["all"]

function generateUniqueSlug(text: string, existingIds: string[], currentId?: string): string {
  const baseSlug = slugify(text)
  const allReservedIds = [...existingIds, ...RESERVED_TAB_IDS]

  // If the base slug is available (or matches current ID being renamed), use it
  if (
    (!allReservedIds.includes(baseSlug) || baseSlug === currentId) &&
    !RESERVED_TAB_IDS.includes(baseSlug)
  ) {
    return baseSlug
  }

  // Otherwise, find a unique suffix
  let counter = 2
  while (
    allReservedIds.includes(`${baseSlug}-${counter}`) &&
    `${baseSlug}-${counter}` !== currentId
  ) {
    counter++
  }
  return `${baseSlug}-${counter}`
}

function formatDate(dateString: string): string {
  const date = new Date(dateString)
  return date.toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  })
}

