          await queueUserRepoSync(c.env.USER_REPO_SYNC_QUEUE, userId, "new_user")
        }

        console.log(`First visit for user ${user.github_login}, repos syncing in background`)
        const attempts = await getSyncAttempts(c.env.ENTIRE_CACHE, userId)
        return c.json({
          repos: [],
          updated_at: new Date().toISOString(),
          from_db: false,
          syncing: true, // Indicate sync is in progress
          sync_error:
            attempts > MAX_INITIAL_SYNC_ATTEMPTS
              ? {
                  code: "initial_sync_failed",
