      await db.repos.upsertForUser(userId, reposToUpsert, installationRepoIds, c.env.ENTIRE_CACHE)

      const dbReposForUser = await db.repos.getForUser(userId)
      const repoIdByFullName = new Map(
        dbReposForUser.map((repo: { full_name: string; id: string }) => [repo.full_name, repo.id]),
      )

      const now = new Date().toISOString()

      // Return repos (filter out forks unless user explicitly granted app access)
      const repos = reposToUpsert
        .filter((r) => !r.is_archived)
        .filter((r) => !r.is_fork || installationRepoIds.has(r.github_id))
