// --- Search Functions ---

export async function getAccessibleReposByUser(
  db: Kysely<DB>,
  userId: string,
): Promise<Array<{ id: string; github_id: number; full_name: string }>> {
  return db
    .selectFrom("repos")
    .innerJoin("user_repos", "user_repos.repo_id", "repos.id")
    .where("user_repos.user_id", "=", userId)
    .where("repos.checkpoint_count", ">", 0)
    .select(["repos.id", "repos.github_id", "repos.full_name"])
    .execute()
}

export async function searchReposByUser(
  db: Kysely<DB>,
  userId: string,
  opts: { query: string; repo?: string; limit: number },
): Promise<any[]> {
  const escapedQuery = opts.query.replace(/[\\%_]/g, "\\$&")

  let q = db
    .selectFrom("repos")
    .innerJoin("user_repos", "user_repos.repo_id", "repos.id")
    .where("user_repos.user_id", "=", userId)
    .where((eb) =>
      eb.or([
        eb("repos.name", "like", `%${escapedQuery}%`),
        eb("repos.description", "like", `%${escapedQuery}%`),
      ]),
    )
    .select([
      "repos.id",
      "repos.github_id",
      "repos.name",
      "repos.full_name",
      "repos.description",
      "repos.checkpoint_count",
    ])

  if (opts.repo) {
    q = q.where("repos.full_name", "=", opts.repo)
  }

  return q.limit(opts.limit).execute()
}

