// Hono middleware utilities

import type { Context, Next } from "hono"
import { getCookie } from "hono/cookie"
import { createMiddleware } from "hono/factory"

import { isAdmin, type Env, type Variables } from "../env"
import { timingSafeEqual, sha256Hex, API_TOKEN_PREFIX } from "./crypto"
import { getDb } from "./db"
import { getSession } from "./session"
import { nullIfInvalidUuid } from "./uuid"

export type AuthenticatedVariables = Pick<Variables, "userId" | "tokenScope" | "authTimestamp">

async function optionalSessionAuth(
  c: Context<{ Bindings: Env; Variables: Variables }>,
): Promise<void> {
  const sessionToken = getCookie(c, "session")

  if (!sessionToken) {
    return
  }

  try {
    const session = await getSession(c.env.ENTIRE_CACHE, sessionToken)
    if (session) {
      c.set("userId", session.userId)
    }
  } catch {
    // KV transient error — degrade to unauthenticated rather than crashing
  }
}

async function requireSessionAuth(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  next: Next,
): Promise<Response | void> {
  c.set("authTimestamp", Date.now())
  const sessionToken = getCookie(c, "session")

  if (!sessionToken) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const session = await getSession(c.env.ENTIRE_CACHE, sessionToken)

  if (!session) {
    return c.json({ error: "Session expired" }, 401)
  }

  const method = c.req.method
  if (method === "POST" || method === "PUT" || method === "DELETE" || method === "PATCH") {
    const csrfCookie = getCookie(c, "csrf")
    const csrfHeader = c.req.header("X-CSRF-Token")

    let csrfFailureReason: string | null = null
    if (!csrfCookie && !csrfHeader) {
      csrfFailureReason = "missing_both"
    } else if (!csrfCookie) {
      csrfFailureReason = "missing_cookie"
    } else if (!csrfHeader) {
      csrfFailureReason = "missing_header"
    } else if (!(await timingSafeEqual(csrfCookie, csrfHeader))) {
      csrfFailureReason = "mismatch"
    }

    if (csrfFailureReason) {
      console.log(
        `[csrf] validation_failed`,
        JSON.stringify({
          reason: csrfFailureReason,
          method,
          path: c.req.path,
          userId: session.userId,
        }),
      )
      return c.json({ error: "CSRF token invalid" }, 403)
    }
  }

  c.set("userId", session.userId)
  await next()
}

export const optionalAuth = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  await optionalSessionAuth(c)
  await next()
})

const RATE_LIMIT_WINDOW_SECONDS = 60
const RATE_LIMIT_MAX_REQUESTS = 60
const AUTH_RATE_LIMIT_WINDOW_SECONDS = 60
const AUTH_RATE_LIMIT_MAX_REQUESTS = 10

async function enforceRateLimit(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  key: string,
  maxRequests: number,
  windowSeconds: number,
): Promise<Response | null> {
  const bucket = Math.floor(Date.now() / 1000 / windowSeconds)
  const bucketKey = `${key}:${bucket}`
  const current = await c.env.ENTIRE_CACHE.get<number>(bucketKey, "json")
  const count = current ?? 0

  if (count >= maxRequests) {
    return c.json({ error: "Rate limit exceeded" }, 429)
  }

  await c.env.ENTIRE_CACHE.put(bucketKey, JSON.stringify(count + 1), {
    expirationTtl: windowSeconds * 2,
  })

  return null
}

export const rateLimitUnauthenticated = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  const userId = c.get("userId")
  if (userId) {
    await next()
    return
  }

  const ip = c.req.header("cf-connecting-ip") || "unknown"
  const limited = await enforceRateLimit(
    c,
    `ratelimit:unauth:${ip}`,
    RATE_LIMIT_MAX_REQUESTS,
    RATE_LIMIT_WINDOW_SECONDS,
  )

  if (limited) {
    return limited
  }

  await next()
})

export const rateLimitAuthenticated = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  const userId = c.get("userId")
  if (!userId) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const limited = await enforceRateLimit(
    c,
    `ratelimit:auth:${userId}`,
    AUTH_RATE_LIMIT_MAX_REQUESTS,
    AUTH_RATE_LIMIT_WINDOW_SECONDS,
  )

  if (limited) {
    return limited
  }

  await next()
})

export const requireAuth = createMiddleware<{
  Bindings: Env
  Variables: AuthenticatedVariables
}>(async (c, next) => {
  return requireSessionAuth(c, next)
})

// Require Bearer token auth (for CLI/API clients using ent_ tokens)
export const requireBearerAuth = createMiddleware<{
  Bindings: Env
  Variables: AuthenticatedVariables
}>(async (c, next) => {
  const authHeader = c.req.header("Authorization")

  if (!authHeader) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const parts = authHeader.split(" ")
  if (parts.length !== 2 || parts[0] !== "Bearer") {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const token = parts[1]
  if (!token.startsWith(API_TOKEN_PREFIX)) {
    return c.json({ error: "Not authenticated" }, 401)
  }

