export async function getInstallationToken(
  installationId: number,
  config: AppTokenConfig,
  kv?: KVNamespace,
): Promise<string> {
  const cacheKey = `installation_token:${installationId}`

  // Check cache first
  if (kv) {
    const cached = await kv.get(cacheKey)
    if (cached) {
      return cached
    }
  }

  // Create JWT for app authentication
  const jwt = await createAppJWT(config.appId, config.privateKey)

  // Request installation access token from GitHub
  const response = await fetch(
    `https://api.github.com/app/installations/${installationId}/access_tokens`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${jwt}`,
        Accept: "application/vnd.github+json",
        "User-Agent": "entire-api",
        "X-GitHub-Api-Version": "2022-11-28",
      },
    },
  )

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Failed to get installation token: ${response.status} - ${errorText}`)
  }

  const data = await response.json<{ token: string; expires_at: string }>()

  // Cache the token
  if (kv) {
    await kv.put(cacheKey, data.token, { expirationTtl: INSTALLATION_TOKEN_CACHE_TTL })
  }

  return data.token
}

/**
 * Get a valid GitHub access token, refreshing if expired.
 * Returns the decrypted access token ready to use.
 *
 * @param kv - Optional KV namespace to invalidate user cache on token refresh
 */
export async function getValidGitHubToken(
  db: Db,
  user: Pick<
    User,
    "id" | "github_token_enc" | "github_refresh_token_enc" | "github_token_expires_at"
  >,
  config: TokenConfig,
  kv?: KVNamespace,
): Promise<TokenResult> {
  if (!user.github_token_enc) {
    throw new Error("User has no GitHub token")
  }

  const now = Date.now()
  const expiresAt = user.github_token_expires_at
    ? new Date(user.github_token_expires_at).getTime()
    : null

  // Check if token is expired or about to expire
  const isExpired = expiresAt && now >= expiresAt - EXPIRATION_BUFFER_MS

  if (!isExpired) {
    // Token is still valid
    const token = await decrypt(user.github_token_enc, config.encryptionKey)
    return { token, refreshed: false }
  }

  // Token is expired - try to refresh
  if (!user.github_refresh_token_enc) {
    // No refresh token available - return current token and hope for the best
    // User will need to re-authenticate if it fails
    console.warn(`Token expired for user ${user.id} but no refresh token available`)
    const token = await decrypt(user.github_token_enc, config.encryptionKey)
    return { token, refreshed: false }
  }

  console.log(`Refreshing expired token for user ${user.id}`)

  try {
    const refreshToken = await decrypt(user.github_refresh_token_enc, config.encryptionKey)

    const tokenData = await refreshAccessToken(refreshToken, config.clientId, config.clientSecret)

    // Encrypt new tokens
    const encryptedToken = await encrypt(tokenData.access_token, config.encryptionKey)
    const encryptedRefreshToken = tokenData.refresh_token
      ? await encrypt(tokenData.refresh_token, config.encryptionKey)
      : user.github_refresh_token_enc // Keep old refresh token if not returned

    const tokenExpiresAt = tokenData.expires_in
      ? new Date(Date.now() + tokenData.expires_in * 1000).toISOString()
      : null

    // Update user with new tokens
    await db.users.update(user.id, {
      github_token_enc: encryptedToken,
      github_refresh_token_enc: encryptedRefreshToken,
      github_token_expires_at: tokenExpiresAt,
    })

    // Invalidate user cache so subsequent requests get fresh token data
    if (kv) {
      await kv.delete(`user:${user.id}`)
    }

    console.log(`Successfully refreshed token for user ${user.id}`)
    return { token: tokenData.access_token, refreshed: true }
  } catch (err) {
    console.error(`Failed to refresh token for user ${user.id}: ${errorString(err)}`)

    // Re-read user from DB - another request may have already refreshed successfully
    try {
      const freshUser = await db.users.findById(user.id)
      if (freshUser?.github_token_enc && freshUser.github_token_enc !== user.github_token_enc) {
        console.log(`Using token refreshed by concurrent request for user ${user.id}`)
        const token = await decrypt(freshUser.github_token_enc, config.encryptionKey)
        return { token, refreshed: true }
      }
    } catch (dbErr) {
      console.error(`Failed to re-read user ${user.id} from DB: ${errorString(dbErr)}`)
    }

    // No concurrent refresh happened (or DB unavailable) - return the old token
    const token = await decrypt(user.github_token_enc, config.encryptionKey)
    return { token, refreshed: false }
  }
}

