// Require Bearer token auth (for CLI/API clients using ent_ tokens)
export const requireBearerAuth = createMiddleware<{
  Bindings: Env
  Variables: AuthenticatedVariables
}>(async (c, next) => {
  const authHeader = c.req.header("Authorization")

  if (!authHeader) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const parts = authHeader.split(" ")
  if (parts.length !== 2 || parts[0] !== "Bearer") {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const token = parts[1]
  if (!token.startsWith(API_TOKEN_PREFIX)) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const hash = await sha256Hex(token)
  const db = getDb(c.env)
  const lookup = await db.apiTokens.findByTokenHash(hash)

  if (!lookup) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  // Check expiration
  if (new Date(lookup.expires_at) < new Date()) {
    return c.json({ error: "Token expired" }, 401)
  }

  c.set("userId", lookup.user_id)
  c.set("tokenScope", lookup.scope)

  // Fire-and-forget: update last_used_at
  try {
    c.executionCtx.waitUntil(db.apiTokens.updateLastUsedAt(lookup.id))
  } catch {
    // executionCtx not available (e.g. in tests) — run inline
    void db.apiTokens.updateLastUsedAt(lookup.id)
  }

  await next()
})

// Accept either session-cookie auth (with CSRF for mutating methods) or
// Bearer token auth. We intentionally delegate to the existing middlewares so
// session and bearer semantics stay identical to the rest of the app.
export const requireAuthOrBearer = createMiddleware<{
  Bindings: Env
  Variables: AuthenticatedVariables
}>(async (c, next) => {
  const authHeader = c.req.header("Authorization")

  if (authHeader?.startsWith("Bearer ")) {
    return requireBearerAuth(c, next)
  }

  return requireAuth(c, next)
})

