/**
 * Base64URL encode a buffer (RFC 4648)
 */
function base64UrlEncode(data: Uint8Array | ArrayBuffer): string {
  const bytes = data instanceof ArrayBuffer ? new Uint8Array(data) : data
  const base64 = btoa(String.fromCharCode(...bytes))
  return base64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "")
}

/**
 * Create a JWT for GitHub App authentication.
 * The JWT is signed with RS256 using the app's private key.
 */
export async function createAppJWT(appId: string, privateKeyPem: string): Promise<string> {
  const now = Math.floor(Date.now() / 1000)

  // JWT header
  const header = {
    alg: "RS256",
    typ: "JWT",
  }

  // JWT payload - issued 60 seconds in the past to allow for clock drift
  // Expires in 10 minutes (max allowed by GitHub)
  const payload = {
    iat: now - 60,
    exp: now + 600,
    iss: appId,
  }

  const encoder = new TextEncoder()
  const headerB64 = base64UrlEncode(encoder.encode(JSON.stringify(header)))
  const payloadB64 = base64UrlEncode(encoder.encode(JSON.stringify(payload)))
  const signingInput = `${headerB64}.${payloadB64}`

  // Import the private key for signing
  const key = await importPrivateKey(privateKeyPem)

  // Sign the JWT
  const signature = await crypto.subtle.sign(
    { name: "RSASSA-PKCS1-v1_5" },
    key,
    encoder.encode(signingInput),
  )

  const signatureB64 = base64UrlEncode(signature)

  return `${signingInput}.${signatureB64}`
}

/**
 * Import a PEM-encoded RSA private key for use with Web Crypto API.
 */
async function importPrivateKey(pemKey: string): Promise<CryptoKey> {
  // Remove PEM headers and whitespace
  const pemContents = pemKey
    .replace(/REDACTED/, "")
    .replace(/-----END PRIVATE KEY-----/, "")
    .replace(/\s/g, "")

  // Decode base64 to binary
  const binaryString = atob(pemContents)
  const bytes = new Uint8Array(binaryString.length)
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i)
  }

  // Import as PKCS#8 (PRIVATE KEY) or try PKCS#1 (RSA PRIVATE KEY)
  try {
    return await crypto.subtle.importKey(
      "pkcs8",
      bytes,
      { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
      false,
      ["sign"],
    )
  } catch {
    // If PKCS#8 fails, the key might be PKCS#1 format
    // PKCS#1 keys need to be wrapped in PKCS#8 format
    throw new Error(
      "Failed to import private key. Ensure the key is in PKCS#8 format (BEGIN PRIVATE KEY)",
    )
  }
}

/**
 * Get a GitHub App installation access token.
 * Uses the app's JWT to authenticate and request a token for the specific installation.
 * Tokens are cached in KV for 50 minutes (expire after 1 hour).
 *
 * @param installationId - The GitHub App installation ID
 * @param config - App authentication config (appId and privateKey)
 * @param kv - KV namespace for caching tokens
 * @returns The installation access token
 */
export async function getInstallationToken(
  installationId: number,
  config: AppTokenConfig,
  kv?: KVNamespace,
): Promise<string> {
  const cacheKey = `installation_token:${installationId}`

  // Check cache first
  if (kv) {
    const cached = await kv.get(cacheKey)
    if (cached) {
      return cached
    }
  }

  // Create JWT for app authentication
  const jwt = await createAppJWT(config.appId, config.privateKey)

  // Request installation access token from GitHub
  const response = await fetch(
    `https://api.github.com/app/installations/${installationId}/access_tokens`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${jwt}`,
        Accept: "application/vnd.github+json",
        "User-Agent": "entire-api",
        "X-GitHub-Api-Version": "2022-11-28",
      },
    },
  )

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Failed to get installation token: ${response.status} - ${errorText}`)
  }

  const data = await response.json<{ token: string; expires_at: string }>()

  // Cache the token
  if (kv) {
    await kv.put(cacheKey, data.token, { expirationTtl: INSTALLATION_TOKEN_CACHE_TTL })
  }

  return data.token
}

