      github_token_enc: encryptedToken,
      github_refresh_token_enc: encryptedRefreshToken,
      github_token_expires_at: tokenExpiresAt,
    })

    // Invalidate user cache so subsequent requests get fresh token data
    if (kv) {
      await kv.delete(`user:${user.id}`)
    }

    console.log(`Successfully refreshed token for user ${user.id}`)
    return { token: tokenData.access_token, refreshed: true }
  } catch (err) {
    console.error(`Failed to refresh token for user ${user.id}: ${errorString(err)}`)

    // Re-read user from DB - another request may have already refreshed successfully
    try {
      const freshUser = await db.users.findById(user.id)
      if (freshUser?.github_token_enc && freshUser.github_token_enc !== user.github_token_enc) {
        console.log(`Using token refreshed by concurrent request for user ${user.id}`)
        const token = await decrypt(freshUser.github_token_enc, config.encryptionKey)
        return { token, refreshed: true }
      }
    } catch (dbErr) {
      console.error(`Failed to re-read user ${user.id} from DB: ${errorString(dbErr)}`)
    }

    // No concurrent refresh happened (or DB unavailable) - return the old token
    const token = await decrypt(user.github_token_enc, config.encryptionKey)
    return { token, refreshed: false }
  }
}

