const fs = require("fs");
const token = process.env.GITHUB_TOKEN;
const headers = { Authorization: `Bearer ${token}`, Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "entire-migrate-v2" };
const cutoff = Date.now() - 3 * 24 * 60 * 60 * 1000;
async function gh(url) {
  const res = await fetch(url, { headers });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`${res.status} ${url}: ${await res.text()}`);
  return res.json();
}
async function listRepos() {
  const repos = [];
  for (let page = 1; page <= 20; page++) {
    const url = `https://api.github.com/user/repos?visibility=private&affiliation=owner,collaborator,organization_member&sort=pushed&direction=desc&per_page=100&page=${page}`;
    const batch = await gh(url);
    repos.push(...batch);
    if (batch.length < 100) break;
  }
  return repos;
}
async function hasRef(repo, ref) {
  const encoded = ref.split("/").map(encodeURIComponent).join("/");
  const res = await fetch(`https://api.github.com/repos/${repo.full_name}/git/ref/${encoded}`, { headers });
  if (res.status === 404) return false;
  if (!res.ok) throw new Error(`${repo.full_name} ref ${ref}: ${res.status} ${await res.text()}`);
  return true;
}
const repos = await listRepos();
const oldPrivate = repos.filter(r => r.private && !r.archived && new Date(r.pushed_at || r.updated_at).getTime() <= cutoff);
const candidates = [];
const withCheckpoints = [];
for (const repo of oldPrivate) {
  const hasV1 = await hasRef(repo, "heads/entire/checkpoints/v1");
  const hasV2Main = await hasRef(repo, "entire/checkpoints/v2/main").catch(() => false);
  const hasV2Full = await hasRef(repo, "entire/checkpoints/v2/full/current").catch(() => false);
  if (hasV1 || hasV2Main || hasV2Full) {
    const entry = {
      full_name: repo.full_name,
      name: repo.name,
      html_url: repo.html_url,
      clone_url: repo.clone_url,
      ssh_url: repo.ssh_url,
      default_branch: repo.default_branch,
      pushed_at: repo.pushed_at || repo.updated_at,
      private: repo.private,
      has_v1_ref: hasV1,
      has_v2_main_ref: hasV2Main,
      has_v2_full_ref: hasV2Full,
    };
    withCheckpoints.push(entry);
    candidates.push(entry);
  }
}
fs.writeFileSync("/tmp/migrate-v2-candidates.json", JSON.stringify(candidates, null, 2) + "\n");
console.log(JSON.stringify({total_private_repos: repos.length, old_private_repos: oldPrivate.length, checkpoint_candidates: candidates.length, cutoff: new Date(cutoff).toISOString(), repos: candidates.map(r => ({full_name:r.full_name, pushed_at:r.pushed_at, default_branch:r.default_branch, has_v1_ref:r.has_v1_ref, has_v2_main_ref:r.has_v2_main_ref}))}, null, 2));
