(async () => {
const fs = require("fs");
const token = process.env.GITHUB_TOKEN;
const headers = { Authorization: `Bearer ${token}`, Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "entire-migrate-v2" };
const title = "Dual write to checkpoints v1 and v2";
const body = "This is a settings update to dual-write to checkpoints v1 and v2 as part of the checkpoints v2 migration plan. Please see the RFD in https://github.com/entirehq/company-knowledge/pull/51 for more details.";
