  const [full_name, branch, base, sha] = line.split(/\t/);
  return { full_name, branch, base, sha };
});
async function request(url, opts={}) {
  const res = await fetch(url, { ...opts, headers: { ...headers, ...(opts.headers || {}) } });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = { raw: text }; }
  return { res, data, text };
}
const results = [];
for (const row of rows) {
  const [owner, repo] = row.full_name.split("/");
  const create = await request(`https://api.github.com/repos/${owner}/${repo}/pulls`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, body, head: row.branch, base: row.base, draft: false }),
  });
  if (create.res.ok) {
    results.push({ ...row, status: "created", number: create.data.number, url: create.data.html_url });
    console.log(`CREATED ${row.full_name} #${create.data.number} ${create.data.html_url}`);
    continue;
  }
  const existing = await request(`https://api.github.com/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${row.branch}`)}&base=${encodeURIComponent(row.base)}&state=open&per_page=5`);
  if (existing.res.ok && Array.isArray(existing.data) && existing.data.length > 0) {
    const pr = existing.data[0];
    results.push({ ...row, status: "existing", number: pr.number, url: pr.html_url, create_error_status: create.res.status });
    console.log(`EXISTS ${row.full_name} #${pr.number} ${pr.html_url}`);
    continue;
  }
  results.push({ ...row, status: "failed", error_status: create.res.status, error: create.data });
  console.log(`FAILED ${row.full_name} ${create.res.status} ${JSON.stringify(create.data).slice(0,300)}`);
}
fs.writeFileSync("/tmp/migrate-v2-prs.json", JSON.stringify(results, null, 2) + "\n");
const failed = results.filter(r => r.status === "failed");
if (failed.length) process.exitCode = 1;
})().catch(e => { console.error(e && e.stack || e); process.exit(1); });
